// Generates the small test files in WheelCore/Tests/WheelCoreTests/Fixtures.
// Usage: swift scripts/make-fixtures.swift WheelCore/Tests/WheelCoreTests/Fixtures
// The files are committed; rerun only to recreate them. Encoders can differ slightly
// between macOS versions, so regenerated bytes may not match the committed ones.

import CoreGraphics
import Foundation
import ImageIO
import UniformTypeIdentifiers

let folder = URL(filePath: CommandLine.arguments[1], directoryHint: .isDirectory)
try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)

func write(_ data: Data, _ name: String) throws {
    try data.write(to: folder.appending(path: name))
    print("wrote \(name) (\(data.count) bytes)")
}

// A 16x16 solid red image. HEIC encoding fails for very small sizes, so not smaller.
let size = 16
let context = CGContext(
    data: nil, width: size, height: size, bitsPerComponent: 8, bytesPerRow: 0,
    space: CGColorSpace(name: CGColorSpace.sRGB)!, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
context.setFillColor(CGColor(red: 1, green: 0, blue: 0, alpha: 1))
context.fill(CGRect(x: 0, y: 0, width: size, height: size))
let image = context.makeImage()!

func encode(_ type: UTType) -> Data {
    let data = NSMutableData()
    let destination = CGImageDestinationCreateWithData(data, type.identifier as CFString, 1, nil)!
    CGImageDestinationAddImage(destination, image, nil)
    precondition(CGImageDestinationFinalize(destination), "encoding \(type.identifier) failed")
    return data as Data
}

let png = encode(.png)
try write(png, "red.png")
try write(encode(.jpeg), "red.jpg")
try write(encode(.heic), "red.heic")
// Readable by Image I/O but not a v1 input format.
try write(encode(.tiff), "red.tiff")
// PNG content behind a JPEG name.
try write(png, "png-named.jpg")
// PNG signature plus the start of the header chunk, cut before the dimensions.
try write(png.prefix(20), "header-cut.png")
try write(Data(), "empty.png")
try write(Data("Not an image.\n".utf8), "notes.txt")
try write(Data("%PDF-1.7\nThis is not a real PDF.\n".utf8), "damaged.pdf")

// A one-page PDF drawn with Core Graphics.
let pdfData = NSMutableData()
var mediaBox = CGRect(x: 0, y: 0, width: 200, height: 100)
let pdf = CGContext(consumer: CGDataConsumer(data: pdfData)!, mediaBox: &mediaBox, nil)!
pdf.beginPDFPage(nil)
pdf.setFillColor(CGColor(red: 0, green: 0, blue: 1, alpha: 1))
pdf.fill(CGRect(x: 20, y: 20, width: 160, height: 60))
pdf.endPDFPage()
pdf.closePDF()
try write(pdfData as Data, "one-page.pdf")
